"""Build src/lib/features.js: IAU-named features per Mars Chart quadrangle.
Source: NASA Mars Trek nomenclature index (IAU/USGS Gazetteer of Planetary Nomenclature), retrieved 2026-11-15 per
quadrangle bounding box -> data/source/nomenclature/trek_nomenclature_by_quadrangle.json.
'rank' only orders features for display (which few to show first); it is an editorial choice, not data."""
import json, os, re
ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')
raw = json.load(open(os.path.join(ROOT, 'data/source/nomenclature/trek_nomenclature_by_quadrangle.json')))
NAMES = ['Mare Boreum', 'Diacria', 'Arcadia', 'Mare Acidalium', 'Ismenius Lacus', 'Casius', 'Cebrenia', 'Amazonis', 'Tharsis', 'Lunae Palus', 'Oxia Palus', 'Arabia',
         'Syrtis Major', 'Amenthes', 'Elysium', 'Memnonia', 'Phoenicis Lacus', 'Coprates', 'Margaritifer Sinus', 'Sinus Sabaeus', 'Iapygia', 'Mare Tyrrhenum', 'Aeolis',
         'Phaethontis', 'Thaumasia', 'Argyre', 'Noachis', 'Hellas', 'Eridania', 'Mare Australe']
quads = [(65, 90, 0, 360)] + [(30, 65, (180 + 60 * i) % 360, (180 + 60 * i) % 360 + 60) for i in range(6)] + [(0, 30, (180 + 45 * i) % 360, (180 + 45 * i) % 360 + 45) for i in range(8)] \
    + [(-30, 0, (180 + 45 * i) % 360, (180 + 45 * i) % 360 + 45) for i in range(8)] + [(-65, -30, (180 + 60 * i) % 360, (180 + 60 * i) % 360 + 60) for i in range(6)] + [(-90, -65, 0, 360)]
TYPE = {'Mons, montes': 10, 'Planitia, planitiae': 10, 'Vastitas, vastitates': 9, 'Planum, plana': 9, 'Chasma, chasmata': 9, 'Terra, terrae': 8, 'Labyrinthus, labyrinthi': 8,
        'Vallis, valles': 7, 'Patera, paterae': 6, 'Tholus, tholi': 6, 'Fossa, fossae': 6, 'Chaos, chaoses': 5, 'Unda, undae': 5, 'Mensa, mensae': 4, 'Palus, paludes': 4,
        'Crater, craters': 3, 'Dorsum, dorsa': 3, 'Sulcus, sulci': 3, 'Rupes, rupes': 3, 'Collis, colles': 3, 'Catena, catenae': 2, 'Scopulus, scopuli': 2, 'Cavus, cavi': 2}
WELL_KNOWN = set('''Olympus Mons|Valles Marineris|Gale|Jezero|Gusev|Hellas Planitia|Argyre Planitia|Elysium Mons|Tharsis Montes|Ascraeus Mons|Pavonis Mons|Arsia Mons|Alba Mons|Utopia Planitia|
Chryse Planitia|Isidis Planitia|Syrtis Major Planum|Nili Fossae|Noctis Labyrinthus|Meridiani Planum|Ares Vallis|Kasei Valles|Mawrth Vallis|Holden|Eberswalde|Korolev|Planum Boreum|Planum Australe|
Olympia Undae|Chasma Boreale|Chasma Australe|Schiaparelli|Huygens|Cassini|Arabia Terra|Amazonis Planitia|Acidalia Planitia|Arcadia Planitia|Cerberus Fossae|Medusae Fossae|Apollinaris Mons|
Hadriacus Mons|Tyrrhenus Mons|Ma'adim Vallis|Dao Vallis|Coprates Chasma|Candor Chasma|Melas Chasma|Ius Chasma|Hebes Chasma|Echus Chasma|Lunae Planum|Solis Planum|Syria Planum|Daedalia Planum|
Claritas Fossae|Thaumasia Planum|Aram Chaos|Margaritifer Terra|Noachis Terra|Terra Sirenum|Terra Cimmeria|Promethei Terra|Hesperia Planum|Malea Planum|Aonia Terra|Lowell|Newton|Copernicus|Galle|
Lyot|Deuteronilus Mensae|Protonilus Mensae|Nilosyrtis Mensae|Phlegra Montes|Hecates Tholus|Albor Tholus|Orcus Patera|Mie|Milankovic|Tempe Terra|Uranius Mons|Ceraunius Tholus|Mangala Valles|
Tooting|Marte Vallis|Hale|Antoniadi|Terra Sabaea|Tyrrhena Terra|Herschel|Aeolis Mons|Elysium Planitia|Athabasca Valles|Kepler|Reull Vallis|Hellespontus Montes|Vastitas Borealis|Libya Montes|
Ganges Chasma|Eos Chasma|Capri Chasma|Nirgal Vallis|Uzboi Vallis|Tiu Valles|Simud Valles|Maja Valles|Shalbatana Vallis|Xanthe Terra|Nepenthes Mensae|Amenthes Planum|Tartarus Montes|
Charitum Montes|Nereidum Montes|Sirenum Fossae|Icaria Planum|Sinai Planum|Bosporos Planum|Peneus Patera|Amphitrites Patera|Harmakhis Vallis|Niger Vallis|Dorsa Argentea|Ultimi Scopuli|
Australe Scopuli|Promethei Planum|Flammarion'''.replace('\n', '').split('|'))
PIN = {'MC-13': ['Syrtis Major Planum', 'Jezero', 'Nili Fossae', 'Isidis Planitia']}   # the demo region: features named in the design brief
out = {}
for i, (s, n, w, e) in enumerate(quads):
    key = '%d_%d_%d_%d' % (w, e, s, n); mc = 'MC-%02d' % (i + 1); seen = {}
    for x in raw[key]:
        if x['type'] in ('Albedo Feature', 'Unofficial', None): continue
        lon, lat = map(float, re.match(r'POINT \(([-\d.]+) ([-\d.]+)\)', x['shape']).groups()); lon %= 360
        if not (s <= lat <= n and (w <= lon <= e or (w == 0 and e == 360))): continue
        name = re.sub(r'\s+', ' ', x['name']).strip()
        rank = TYPE.get(x['type'], 1) + (20 if name in WELL_KNOWN else 0) + (1000 - 10 * PIN[mc].index(name) if name in PIN.get(mc, []) else 0)
        seen[name] = [name, x['type'].split(',')[0], round(lat, 4), round(lon, 4), rank]
    out[mc] = sorted(seen.values(), key=lambda f: (-f[4], f[0]))
open(os.path.join(ROOT, 'src/lib/features.js'), 'w').write(
    '// GENERATED by scripts/build_features.py — IAU-named features per Mars Chart quadrangle (NASA Mars Trek nomenclature index,\n'
    '// IAU/USGS Gazetteer; retrieved 2026-11-15). Rows: [name, type, lat °N planetocentric, lon °E, display rank]. Do not edit.\n'
    'export const FEATURES = ' + json.dumps(out, separators=(',', ':'), ensure_ascii=False) + ';\n')
print(sum(len(v) for v in out.values()), 'features;', {k: [f[0] for f in v[:4]] for k, v in out.items()})
